import { useEffect, useState } from "react";
import axios from "axios";
import { Box, Button, Modal, Typography, Grid, Paper } from "@mui/material";
import { useDropzone } from "react-dropzone";

const ImageUpload = () => {
  const [images, setImages] = useState({ slider: [], bigphoto: [], allphoto: [] });
  const [uploadedImages, setUploadedImages] = useState({ slider: [], bigphoto: [], allphoto: [] });
  const [open, setOpen] = useState(false);
  const [GetAllPhotos, setGetAllPhotos] = useState([]);
  const [GetBigPhoto, setGetBigPhoto] = useState([]);
  const [GetSlider, setGetSlider] = useState([]);
  
  const handleDrop = (acceptedFiles, category) => {
    setImages((prev) => ({ ...prev, [category]: [...prev[category], ...acceptedFiles] }));
  };

  const handleUpload = async () => {
    const formData = new FormData();
    Object.keys(images).forEach((category) => {
      images[category].forEach((file) => formData.append(category, file));
    });
    try {
      const response = await axios.post("http://localhost:5000/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      console.log("Upload success:", response.data);
      fetchImages();
    } catch (error) {
      console.error("Error uploading images:", error);
    }
  };

  const fetchImages = async () => {
    try {
      const response = await axios.get("http://localhost:5000/images");

      setGetAllPhotos(response.data?.[0]?.allphoto || []);
      setGetBigPhoto(response.data?.[0]?.bigphoto || []);
      setGetSlider(response.data?.[0]?.slider || []);

    } catch (error) {
      console.error("Error fetching images:", error);
    }
  };

  useEffect(() => {
    fetchImages();
  }, []);

  const Dropzone = ({ category }) => {
    const { getRootProps, getInputProps } = useDropzone({
      onDrop: (acceptedFiles) => handleDrop(acceptedFiles, category),
      accept: "image/*",
    });
    return (
      <Paper
        {...getRootProps()}
        sx={{ p: 2, textAlign: "center", cursor: "pointer", border: "2px dashed gray", mb: 2 }}
      >
        <input {...getInputProps()} />
        <Typography variant="body1">Drag & drop or click to upload {category} images</Typography>
      </Paper>
    );
  };
  return (
    <Box sx={{ p: 3, maxWidth: "600px", margin: "auto", height :'83%', overflow: 'scroll' }}>
      <Typography variant="h4" gutterBottom>Image Upload</Typography>
      <Dropzone category="slider" />
      <Dropzone category="bigphoto" />
      <Dropzone category="allphoto" />
      <Button variant="contained" color="primary" fullWidth sx={{ my: 2 }} onClick={handleUpload}>
        Upload Images
      </Button>
      <Button variant="outlined" fullWidth onClick={() => setOpen(true)}>
        Open Gallery
      </Button>
      {/* Gallery Modal */}
      <Modal open={open} onClose={() => setOpen(false)}>
        <Box sx={{ p: 3, bgcolor: "white", maxWidth: "90%", mx: "auto", my: 5, borderRadius: 2 }}>
          <Typography variant="h5" gutterBottom>Gallery</Typography>
          {Object.keys(uploadedImages).map((category) => (
            <Box key={category} sx={{ my: 2 }}>
              <Typography variant="h6">{category.toUpperCase()}</Typography>
              <Grid container spacing={2}>
                {GetAllPhotos?.map((img, index) => (
                  <Grid item key={index} xs={4}>
                    <img src={img.url} alt={img.filename} style={{ width: "auto", borderRadius: "8px" }} />
                  </Grid>
                ))}
              </Grid>
              <Grid container spacing={2}>
                {GetBigPhoto?.map((img, index) => (
                  <Grid item key={index} xs={4}>
                    <img src={img.url} alt={img.filename} style={{ width: "100%", borderRadius: "8px" }} />
                  </Grid>
                ))}
              </Grid>
              <Grid container spacing={2}>
                {GetSlider?.map((img, index) => (
                  <Grid item key={index} xs={4}>
                    <img src={img.url} alt={img.filename} style={{ width: "100%", borderRadius: "8px" }} />
                  </Grid>
                ))}
              </Grid>
            </Box>
          ))}
        </Box>
      </Modal>
    </Box>
  );
};

export default ImageUpload;
